def norm(s):
    s = unicodedata.normalize('NFD', s.lower()); s = ''.join(c for c in s if unicodedata.category(c) != 'Mn'); return re.sub(r'[^a-z0-9+#]', '', s)
out = []
for cid, (q, hint, spec) in CATS.items():
    rows = []; seenn = set()
    for item in [x.strip() for x in spec.split(';') if x.strip()]:
        head, *aliases = item.split('|')
        name, stems = head.split(':')
        if norm(name) in seenn: continue
        forms = set()
        for st in stems.split(','):
            st = st.strip().lower()
            for s in SUF: forms.add(st + s)
        forms |= {name.lower()} | {a.lower() for a in aliases}
        lemmaset = {name.lower()} | {a.lower() for a in aliases}
        hits = [p for p in corpus if (p['tok'] & forms) or (p['lem'] & lemmaset)]
        if not hits: continue
        seenn.add(norm(name))
        # nejlepší ukázka: slavné české, pak české, pak slovenské; kratší dřív
        hits.sort(key=lambda p: (not p.get('famous'), p['lang'] != 'cs', len(p['t'])))
        note = re.sub(r'\s*\(.*?\)\s*', ' ', hits[0]['t']).strip()
        al = [a for a in aliases if a and not a.isdigit() or cid == 'pr-cislo']
        rows.append((len(hits) + (3 if any(p.get('famous') for p in hits) else 0), name, al, note))
    rows.sort(key=lambda r: -r[0])
    a = '; '.join('|'.join([r[1]] + r[2]) + ' = ' + r[3].replace(';', ',').replace('|', '/') for r in rows)
    out.append({'id': cid, 'pack': 'prov', 'q': q, 'hint': hint, 'a': a})
    print(cid, len(rows), '|', ', '.join(f"{r[1]}({r[0]})" for r in rows[:14]), file=sys.stderr)
